-- Versi baru "Tugas Ingatan" (ME) — 4 varian pasangan kategori-item YANG BERBEDA
-- per varian, supaya siswa yang duduk berdampingan tidak menghafal daftar yang
-- sama persis (lihat lib/anti-curang.js JUMLAH_VERSI_MEMORI & app/api/attempt/start).
-- Set lama (ME_smp_1..20 / ME_sma_1..24, sub_kategori NULL) SENGAJA TIDAK dihapus:
-- masih dipakai untuk menghitung ulang skor sesi-sesi LAMA yang sudah selesai
-- (lihat app/api/attempt/finish/route.js, JOIN ke bank_soal by kode_soal).
-- Sesi BARU tidak pernah lagi mendapat set lama ini (lihat app/api/attempt/start).

alter table sesi_tes add column if not exists versi_memori text;

